function card(path: string, overrides: Partial<Card['header']> = {}, content = ''): Card {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        content,
        hasFrontmatter: false,
        header: {
            affects: [],
            after: null,
            agentLogReferences: [],
            author: null,
            id: 'F-0',
            internalId: path,
            owner: null,
            policy: {},
            status: null,
